-- Restore real uploaded photos for Black T-shirt and Royal Blue Saree
UPDATE public.wardrobe_items
SET image = 'data:image/png;base64,'
WHERE name ILIKE '%tshirt%' OR name ILIKE '%t-shirt%' OR id = 'item-1791713624597';

UPDATE public.wardrobe_items
SET image = 'data:image/png;base64,'
WHERE name ILIKE '%saree%' OR id = 'item-1791721704288';
